// Task 15 — the Phase-1 integration keystone: a black-box HTTP test that
// exercises the COMPOSED handler (web.Handler(api.New(deps), opts)) end-to-end
// across AC-1..AC-7. Assertions are on HTTP status + headers + JSON bodies ONLY
// (INV-black-box) — no internal-package white-box handler calls. Setup may use
// the store directly (the same pattern qa_auth_test.go uses for its library
// counter), but every behavior assertion goes through the HTTP edge.
//
// GROUNDING-DRIVEN DEVIATIONS (flag for reviewer):
//
//  1. internal/scan is imported to build the Deps.Scan stub (scan.Result is the
//     closure return type — it cannot be named without the import). Every
//     sibling repo-root test (integration_test.go, qa_auth_test.go) imports
//     internal/scan for exactly this; the task's allowed_imports under-listed
//     it. This is a structural necessity, not an invented API.
//
//  2. AC-1 client-role 403 path: the synthetic Principal{Role:RoleClient}
//     injection the spec names is NOT constructible from this external test
//     (package mellifera_test) because api.principalKey (the context key) is
//     unexported, and no resolver mints RoleClient today. Widening api's public
//     surface with a test-only injector would violate the <=8 symbol budget, so
//     this test asserts the externally-observable AC-1 slice (admin reaches all
//     6 routes; no/wrong token -> 401) and the client-vs-admin 403 distinction
//     is covered by the in-package internal/api/role_gating_test.go (Task 08),
//     which can name principalKey. This is the "OR real admin" branch the
//     delegation explicitly authorized.
//
//  3. AC-2 verify probe: acceptance.md's `grep -cE '(/libraries|/items|
//     /admin/status)' >= 6` miscounts — the code-generated spec has 5 distinct
//     path keys carrying 6 operations (POST /libraries + GET /libraries share
//     the /libraries key). This test asserts the TRUE invariant: all 5 path
//     keys + all 6 operations are present.
package itest

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/scan"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/web"
)

// webTestAdminToken is the fixed admin token setupWebTest wires into api.Deps.
const webTestAdminToken = "web-test-admin-token"

// webTestPlugins is the known plugin set the admin-status closure returns.
// It mirrors the canonical cmd/mellifera pluginIDs slice (base-scanner,
// tv-parser, image-enricher) so AC-5 asserts the real production shape.
var webTestPlugins = []api.PluginHealth{
	{ID: "base-scanner", State: "serving", Restarts: 0, CheckedAt: "2026-08-05T00:00:00Z"},
	{ID: "tv-parser", State: "serving", Restarts: 0, CheckedAt: "2026-08-05T00:00:00Z"},
	{ID: "image-enricher", State: "serving", Restarts: 1, CheckedAt: "2026-08-05T00:00:00Z"},
}

// webTestEnrich is the enrich snapshot the closure returns.
var webTestEnrich = api.EnrichStats{Pending: 3, InFlight: 1, Done: 42, Failed: 2}

// setupWebTest opens a fresh temp store and builds the composed handler under
// test: web.Handler(api.New(deps), opts). The Deps.Status closure returns a
// populated AdminStatus (exercising the exported seam-input types +
// AdminStatus constructed cross-package — the BLK-T13-1 fix). The Deps.Scan
// stub returns an empty Result silently (the ac1 admin-only scan route
// legitimately triggers it). The returned store lets sub-tests seed items
// for AC-4.
func setupWebTest(t *testing.T) (http.Handler, *store.Store) {
	t.Helper()
	st, err := store.Open(context.Background(), filepath.Join(t.TempDir(), "web.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	apiHandler := api.New(api.Deps{
		AdminToken: webTestAdminToken,
		Store:      st,
		// Scan returns an empty Result silently — the ac1 admin-only scan route
		// legitimately triggers it, so a fail-loud stub (the qa_auth pattern)
		// would be wrong here.
		Scan: func(context.Context, int64) (scan.Result, error) {
			return scan.Result{}, nil
		},
		Status: func(context.Context) (api.AdminStatus, error) {
			// Cross-package construction of AdminStatus — the Option A fix
			// (BLK-T13-1) makes this possible from outside package api.
			return api.AdminStatus{Plugins: webTestPlugins, Enrich: webTestEnrich}, nil
		},
	})
	return web.Handler(apiHandler, web.Options{}), st
}

// webReq builds an authenticated request (or omits the header when token == "").
func webReq(method, target, token string, body []byte) *http.Request {
	r := httptest.NewRequest(method, target, bytes.NewReader(body))
	if token != "" {
		r.Header.Set("Authorization", "Bearer "+token)
	}
	if body != nil {
		r.Header.Set("Content-Type", "application/json")
	}
	return r
}

// webDo dispatches through the handler and returns the recorder.
func webDo(t *testing.T, h http.Handler, r *http.Request) *httptest.ResponseRecorder {
	t.Helper()
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, r)
	return rec
}

type webErrEnvelope struct {
	Error struct {
		Code string `json:"code"`
	} `json:"error"`
}

func webErrCode(t *testing.T, body interface{ Read(p []byte) (int, error) }) string {
	t.Helper()
	var env webErrEnvelope
	if err := json.NewDecoder(body).Decode(&env); err != nil {
		t.Fatalf("decode error envelope: %v", err)
	}
	return env.Error.Code
}

// TestWeb_Integration is the Phase-1 acceptance keystone — one sub-test per AC.
func TestWeb_Integration(t *testing.T) {
	h, st := setupWebTest(t)

	// AC-1: role-gating. Admin reaches every route; no/wrong token -> 401.
	// (Client-role 403 is covered in-package by role_gating_test.go — see the
	// file header deviation note #2.)
	t.Run("ac1_roles", func(t *testing.T) {
		// Seed one item so the browse routes have a target.
		if err := st.PutItem(context.Background(), store.Item{
			ID: "ac1-item", ModuleID: "tv", LibraryID: 1, FileID: "f1",
			RelativePath: "/x", MediaType: "video", Document: json.RawMessage(`{}`),
			Status: "ready",
		}); err != nil {
			t.Fatalf("PutItem: %v", err)
		}
		adminRoutes := []struct {
			method, target string
			want           int
		}{
			{http.MethodGet, "/api/v1/libraries", http.StatusOK},         // browse (admin+client)
			{http.MethodGet, "/api/v1/items?library=1", http.StatusOK},   // browse (library query param required)
			{http.MethodGet, "/api/v1/items/ac1-item", http.StatusOK},    // browse
			{http.MethodPost, "/api/v1/libraries", http.StatusCreated},   // admin only
			{http.MethodGet, "/api/v1/admin/status", http.StatusOK},      // admin only
			{http.MethodPost, "/api/v1/libraries/1/scan", http.StatusOK}, // admin only (Scan stub returns Result{})
		}
		for _, r := range adminRoutes {
			body := []byte(nil)
			if r.method == http.MethodPost && strings.HasSuffix(r.target, "/libraries") {
				body = []byte(`{"module_id":"tv","root_path":"/ac1","display_name":"AC1"}`)
			}
			rec := webDo(t, h, webReq(r.method, r.target, webTestAdminToken, body))
			if rec.Code != r.want {
				t.Errorf("%s %s: status = %d, want %d (body=%s)", r.method, r.target, rec.Code, r.want, rec.Body.String())
			}
		}
		// No/wrong token -> 401 unauthenticated (regression: auth intact inside web.Handler).
		for _, auth := range []string{"", "Bearer " + webTestAdminToken + "-wrong"} {
			rec := webDo(t, h, webReq(http.MethodGet, "/api/v1/libraries", auth, nil))
			if rec.Code != http.StatusUnauthorized {
				t.Errorf("token=%q: status = %d, want %d", auth, rec.Code, http.StatusUnauthorized)
			}
			if code := webErrCode(t, rec.Body); code != "unauthenticated" {
				t.Errorf("token=%q: error code = %q, want unauthenticated", auth, code)
			}
		}
	})

	// AC-2: Swagger served + accurate + public. All 5 path keys + 6 operations
	// present; /docs serves the UI; all reachable without auth.
	t.Run("ac2_swagger", func(t *testing.T) {
		// /openapi.{yaml,json} are served directly (200) and are public (no auth).
		for _, route := range []string{"/openapi.yaml", "/openapi.json"} {
			rec := webDo(t, h, webReq(http.MethodGet, route, "", nil)) // NO auth — public contract
			if rec.Code != http.StatusOK {
				t.Errorf("%s: status = %d, want 200 (public, no auth)", route, rec.Code)
			}
		}
		// YAML accuracy: every path key present.
		yamlBody := webDo(t, h, webReq(http.MethodGet, "/openapi.yaml", "", nil)).Body.String()
		for _, path := range []string{"/libraries", "/libraries/{id}/scan", "/items", "/items/{id}", "/admin/status"} {
			if !strings.Contains(yamlBody, path) {
				t.Errorf("openapi.yaml missing path %q", path)
			}
		}
		// 6 operations (the true AC-2 invariant; the acceptance grep >=6
		// miscounts path-key lines — see file header deviation #3).
		ops := strings.Count(yamlBody, "operationId")
		if ops < 6 {
			t.Errorf("openapi.yaml operationId count = %d, want >= 6", ops)
		}
		// JSON content-type + parses.
		recJSON := webDo(t, h, webReq(http.MethodGet, "/openapi.json", "", nil))
		if ct := recJSON.Header().Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
			t.Errorf("/openapi.json Content-Type = %q, want application/json", ct)
		}
		var spec map[string]any
		if err := json.Unmarshal(recJSON.Body.Bytes(), &spec); err != nil {
			t.Fatalf("/openapi.json not valid JSON: %v", err)
		}
		// /docs/ serves the Swagger UI. httpSwagger serves /docs/ via a 301 to
		// /docs/index.html (browsers follow it); a redirect-following server
		// client is needed to land on the 200 HTML (mirrors web_test.go).
		srv := httptest.NewServer(h)
		defer srv.Close()
		resp, err := http.Get(srv.URL + "/docs/")
		if err != nil {
			t.Fatalf("GET /docs/: %v", err)
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Errorf("/docs/ final status = %d, want 200 (after redirect)", resp.StatusCode)
		}
		if ct := resp.Header.Get("Content-Type"); !strings.HasPrefix(ct, "text/html") {
			t.Errorf("/docs/ Content-Type = %q, want text/html", ct)
		}
	})

	// AC-3: admin can list libraries (id ASC; empty store -> {"items":[]}).
	t.Run("ac3_list", func(t *testing.T) {
		// Empty case first on a fresh handler/store.
		hEmpty, _ := setupWebTest(t)
		rec := webDo(t, hEmpty, webReq(http.MethodGet, "/api/v1/libraries", webTestAdminToken, nil))
		if rec.Code != http.StatusOK {
			t.Fatalf("empty list: status = %d, want 200", rec.Code)
		}
		if strings.TrimSpace(rec.Body.String()) == "" || !strings.Contains(rec.Body.String(), `"items":[]`) {
			t.Errorf("empty list body = %s, want items:[]", rec.Body.String())
		}
		// Create two libraries, then list.
		for _, name := range []string{"LibA", "LibB"} {
			body := []byte(`{"module_id":"tv","root_path":"/` + name + `","display_name":"` + name + `"}`)
			r := webDo(t, h, webReq(http.MethodPost, "/api/v1/libraries", webTestAdminToken, body))
			if r.Code != http.StatusCreated {
				t.Fatalf("create %s: status = %d", name, r.Code)
			}
		}
		rec = webDo(t, h, webReq(http.MethodGet, "/api/v1/libraries", webTestAdminToken, nil))
		if rec.Code != http.StatusOK {
			t.Fatalf("list: status = %d, want 200", rec.Code)
		}
		var resp struct {
			Items []struct {
				ID          int64  `json:"id"`
				ModuleID    string `json:"module_id"`
				RootPath    string `json:"root_path"`
				DisplayName string `json:"display_name"`
			} `json:"items"`
		}
		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
			t.Fatalf("decode libraries: %v", err)
		}
		if len(resp.Items) < 2 {
			t.Fatalf("len(items) = %d, want >= 2", len(resp.Items))
		}
		// id ASC: each id strictly greater than the previous.
		for i := 1; i < len(resp.Items); i++ {
			if resp.Items[i].ID <= resp.Items[i-1].ID {
				t.Errorf("libraries not id ASC: %d before %d", resp.Items[i-1].ID, resp.Items[i].ID)
			}
		}
	})

	// AC-4: client/admin can view an item's FULL document; 404 on missing.
	t.Run("ac4_item", func(t *testing.T) {
		fullDoc := json.RawMessage(`{"sources":{"tv-parser":{"title":"Show"},"image-enricher":{"exif":"GPS"}},"_view":{},"_provenance":{},"_stages":{}}`)
		const itemID = "ac4-ready-item"
		if err := st.PutItem(context.Background(), store.Item{
			ID: itemID, ModuleID: "tv", LibraryID: 1, FileID: "ac4-file",
			RelativePath: "/show/ep1", MediaType: "video", Document: fullDoc,
			SchemaVersion: 1, Status: "ready",
		}); err != nil {
			t.Fatalf("PutItem: %v", err)
		}
		rec := webDo(t, h, webReq(http.MethodGet, "/api/v1/items/"+itemID, webTestAdminToken, nil))
		if rec.Code != http.StatusOK {
			t.Fatalf("get item: status = %d, want 200", rec.Code)
		}
		var resp struct {
			Item struct {
				ID       string          `json:"id"`
				Document json.RawMessage `json:"document"`
				Status   string          `json:"status"`
			} `json:"item"`
		}
		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
			t.Fatalf("decode item: %v", err)
		}
		if resp.Item.ID != itemID {
			t.Errorf("item.id = %q, want %q", resp.Item.ID, itemID)
		}
		// Full document deep-equal (precision preserved — sources/_view/_provenance/_stages).
		var got, want map[string]any
		if err := json.Unmarshal(resp.Item.Document, &got); err != nil {
			t.Fatalf("decode document: %v", err)
		}
		json.Unmarshal(fullDoc, &want)
		if !deepEqualJSON(got, want) {
			t.Errorf("document = %#v, want %#v (full document, precision preserved)", got, want)
		}
		// Missing item -> 404 not_found.
		rec = webDo(t, h, webReq(http.MethodGet, "/api/v1/items/nonexistent", webTestAdminToken, nil))
		if rec.Code != http.StatusNotFound {
			t.Errorf("missing item: status = %d, want 404", rec.Code)
		}
		if code := webErrCode(t, rec.Body); code != "not_found" {
			t.Errorf("missing item: error code = %q, want not_found", code)
		}
	})

	// AC-5: admin status returns the 3 plugins + enrich snapshot through the
	// composed handler (proves the Deps.Status seam + AdminStatus cross-package
	// construction + statusResponse wire shape end-to-end).
	t.Run("ac5_admin_status", func(t *testing.T) {
		rec := webDo(t, h, webReq(http.MethodGet, "/api/v1/admin/status", webTestAdminToken, nil))
		if rec.Code != http.StatusOK {
			t.Fatalf("status = %d, want 200", rec.Code)
		}
		var sr struct {
			Plugins []api.PluginHealth `json:"plugins"`
			Enrich  api.EnrichStats    `json:"enrich"`
		}
		if err := json.Unmarshal(rec.Body.Bytes(), &sr); err != nil {
			t.Fatalf("decode statusResponse: %v", err)
		}
		if len(sr.Plugins) != len(webTestPlugins) {
			t.Fatalf("len(plugins) = %d, want %d", len(sr.Plugins), len(webTestPlugins))
		}
		for i, want := range webTestPlugins {
			if sr.Plugins[i] != want {
				t.Errorf("plugin[%d] = %+v, want %+v", i, sr.Plugins[i], want)
			}
		}
		if sr.Enrich != webTestEnrich {
			t.Errorf("enrich = %+v, want %+v", sr.Enrich, webTestEnrich)
		}
		// Deps.Status == nil -> 503 (the disabled-endpoint invariant).
		hNil := web.Handler(api.New(api.Deps{
			AdminToken: webTestAdminToken, Store: st,
			Scan: func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
			// Status intentionally nil.
		}), web.Options{})
		recNil := webDo(t, hNil, webReq(http.MethodGet, "/api/v1/admin/status", webTestAdminToken, nil))
		if recNil.Code != http.StatusServiceUnavailable {
			t.Errorf("nil Status: status = %d, want 503", recNil.Code)
		}
		if code := webErrCode(t, recNil.Body); code != "unavailable" {
			t.Errorf("nil Status: error code = %q, want unavailable", code)
		}
	})

	// AC-6: SPA served from the Go binary; cache headers + SPA fallback; public.
	t.Run("ac6_embed", func(t *testing.T) {
		// / -> 200 text/html + no-cache, reachable WITHOUT auth.
		rec := webDo(t, h, webReq(http.MethodGet, "/", "", nil))
		if rec.Code != http.StatusOK {
			t.Errorf("/ status = %d, want 200 (public)", rec.Code)
		}
		if ct := rec.Header().Get("Content-Type"); !strings.HasPrefix(ct, "text/html") {
			t.Errorf("/ Content-Type = %q, want text/html", ct)
		}
		if cc := rec.Header().Get("Cache-Control"); !strings.Contains(cc, "no-cache") {
			t.Errorf("/ Cache-Control = %q, want no-cache", cc)
		}
		// A real hashed asset (Vite build) -> 200 + immutable.
		jsAsset := "/assets/app.js" // fallback if discovery fails
		distAssets := filepath.Join(moduleRoot(t), "internal", "web", "dist", "assets")
		if entries, err := os.ReadDir(distAssets); err == nil {
			for _, e := range entries {
				if !e.IsDir() && strings.HasSuffix(e.Name(), ".js") {
					jsAsset = "/assets/" + e.Name()
					break
				}
			}
		}
		rec = webDo(t, h, webReq(http.MethodGet, jsAsset, "", nil))
		if rec.Code != http.StatusOK {
			t.Errorf("%s status = %d, want 200", jsAsset, rec.Code)
		}
		if cc := rec.Header().Get("Cache-Control"); !strings.Contains(cc, "immutable") {
			t.Errorf("%s Cache-Control = %q, want immutable", jsAsset, cc)
		}
		// SPA fallback: an arbitrary client route -> 200 text/html (index.html).
		rec = webDo(t, h, webReq(http.MethodGet, "/some/client/route", "", nil))
		if rec.Code != http.StatusOK {
			t.Errorf("/some/client/route status = %d, want 200 (SPA fallback)", rec.Code)
		}
		if ct := rec.Header().Get("Content-Type"); !strings.HasPrefix(ct, "text/html") {
			t.Errorf("/some/client/route Content-Type = %q, want text/html", ct)
		}
		// Missing hashed asset -> 404 (fail fast, no SPA paper-over).
		rec = webDo(t, h, webReq(http.MethodGet, "/assets/missing.js", "", nil))
		if rec.Code != http.StatusNotFound {
			t.Errorf("/assets/missing.js status = %d, want 404", rec.Code)
		}
	})

	// AC-7: build gate green WITHOUT node + additive probe. Structural shells —
	// skipped under -short so `go test -short` stays fast and CI without make/git
	// does not false-fail.
	t.Run("ac7_gates", func(t *testing.T) {
		if testing.Short() {
			t.Skip("skipping build-gate + additive probe in -short mode")
		}
		if _, err := exec.LookPath("make"); err != nil {
			t.Skip("make not on PATH — skipping build-gate probe (run `make build && make check` manually)")
		}
		for _, target := range []string{"build", "check"} {
			cmd := exec.Command("make", target)
			cmd.Dir = moduleRoot(t) // the Makefile lives at the module root, not the test package dir
			cmd.Stdout = nil
			cmd.Stderr = nil
			if out, err := cmd.CombinedOutput(); err != nil {
				t.Errorf("make %s: exit %v (output: %s)", target, err, out)
			}
		}
		// Additive probe: proto/ byte-identical vs the split-repo baseline
		// f2dc2e8 (the wire CONTRACT tree stays frozen; the 2026-10-14 subtree
		// split is where proto/ first lives at root level, and no sanctioned
		// proto change had landed since). The old pin 58a1130 (the web-ui-era
		// baseline) cannot work in the split repo: its tree predates
		// root-level proto/, so a diff against it reports the directory as
		// all-insertions (13 files, +4057) — vacuously failing on every run.
		// Re-baselining to f2dc2e8 preserves the guard's semantics: "no
		// proto/ change since the sanctioned baseline". Re-baselined to
		// 13e441a by media-data-convention 2.1 (the first sanctioned proto
		// change since f2dc2e8). RETIRED for
		// internal/scan/ internal/enrich/ internal/plugin/ internal/module/:
		// serials-library legitimately extended those sources (the spec'd
		// two-level enrichment queue, serial-record routing, the series sweep,
		// the serial module seed), so they are no longer byte-identical to the
		// web-ui baseline; forward behavior there is guarded by each feature's
		// own spec probes (the serials-library probe set), not by this diff
		// pin.
		// pkg/sdk dropped from the pin: fix-truncated-scan-sweep legitimately
		// reworked the in-repo Scanner surface (ScanStream, wire untouched);
		// the additive guard stays on the wire (proto/) only.
		diff := exec.Command("git", "diff", "--stat", "13e441a", "HEAD", "--",
			"proto/")
		diff.Dir = moduleRoot(t) // git pathspecs resolve against cwd — must be the module root
		out, err := diff.CombinedOutput()
		if err != nil {
			t.Logf("git diff additive probe: %v (output: %s) — continuing", err, out)
		}
		if strings.TrimSpace(string(out)) != "" {
			t.Errorf("additive probe: git diff 13e441a HEAD over proto/ is NON-empty:\n%s", out)
		}
	})
}

// deepEqualJSON compares two decoded JSON values with precision preserved
// (map[string]any / []any / primitives). Used by AC-4 so the full-document
// assertion does not depend on raw-byte formatting (key order, whitespace).
func deepEqualJSON(a, b any) bool {
	switch av := a.(type) {
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for k, v := range av {
			if !deepEqualJSON(v, bv[k]) {
				return false
			}
		}
		return true
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !deepEqualJSON(av[i], bv[i]) {
				return false
			}
		}
		return true
	default:
		return a == b
	}
}
